{
  "name": "ble_ll_rx_pdu_parse",
  "confidence": "medium",
  "docstring": "Processes a received Bluetooth LE link-layer buffer, clearing IRQ 50 when its status/RSSI byte is 0xFF and dispatching LL control PDUs identified by the masked header field to parse_ll_control.",
  "subsystem": "ble",
  "var_renames": {
    "a2": "pdu"
  },
  "struct_hints": [
    {
      "offset": 2,
      "meaning": "link-layer PDU header field; low bits are ignored and a masked value of 0xD0 selects LL control PDUs"
    },
    {
      "offset": 8,
      "meaning": "buffer status/RSSI byte; 0xFF is treated as an invalid or special value"
    }
  ]
}
